from zk_batch import VerificationQueue, ZKVerifier, IncompatibleAggregationError

def proof(pid, key="k1"):
    return {"proof_id": pid, "protocol": "groth16", "circuit_id": "c1",
            "aggregation_key": key, "public_inputs": ["SECRET"], "proof": ("blob", pid)}

class V(ZKVerifier):
    protocol = "groth16"
    def __init__(self, reject=(), errors=(), agg=True):
        self.r, self.e, self.agg = set(reject), set(errors), agg
    def aggregate(self, proofs): return ["A"]
    def verify_aggregate(self, proofs, a): return self.agg
    def verify(self, p):
        if p.proof_id in self.e: raise RuntimeError("boom-SECRET")
        return p.proof_id not in self.r

q = VerificationQueue(V(reject={"z"}, errors={"a"}))
j = q.enqueue({"batch_id": "B", "proofs": [proof("z"), proof("a"), proof("m")]})
q.run_next()
rj = q.reverify_failures(j, V(reject={"z"}, errors={"a"}))
q.run_next()
rep = q.reverify_outcome(j, rj)
import json
print(json.dumps(rep.to_dict(), ensure_ascii=False, indent=1))
